import Foundation

/// `# ATLAS-MANAGED-START <key>` … `# ATLAS-MANAGED-END <key>` blocks: regenerated by Atlas,
/// while everything outside them belongs to the user and is always preserved.
enum HclMerge {
    static let markerStart = "# ATLAS-MANAGED-START"
    static let markerEnd = "# ATLAS-MANAGED-END"

    struct Block {
        let key: String
        let text: String
        let range: Range<String.Index>
    }

    static func blocks(_ content: String) -> [Block] {
        var out: [Block] = []
        var cursor = content.startIndex
        while let start = content.range(of: markerStart + " ", range: cursor..<content.endIndex) {
            guard let lineEnd = content[start.upperBound...].firstIndex(where: \.isNewline) else { break }
            let key = String(content[start.upperBound..<lineEnd]).trimmingCharacters(in: .whitespaces)
            guard let end = content.range(of: "\(markerEnd) \(key)", range: lineEnd..<content.endIndex) else {
                cursor = lineEnd
                continue
            }
            out.append(Block(key: key, text: String(content[start.lowerBound..<end.upperBound]),
                             range: start.lowerBound..<end.upperBound))
            cursor = end.upperBound
        }
        return out
    }

    static func keys(_ content: String) -> [String] { blocks(content).map(\.key) }
    static func hasManagedBlocks(_ content: String) -> Bool { !blocks(content).isEmpty }

    /// Existing managed blocks are replaced by their new version, the ones without a new version are kept,
    /// and new blocks are appended at the end.
    static func merge(existing: String, new: String) -> String {
        var fresh: [String: String] = [:]
        var order: [String] = []
        for b in blocks(new) {
            if fresh[b.key] == nil { order.append(b.key) }
            fresh[b.key] = b.text
        }
        var result = ""
        var last = existing.startIndex
        var placed: Set<String> = []
        for b in blocks(existing) {
            result += existing[last..<b.range.lowerBound]
            if let replacement = fresh[b.key] {
                result += replacement
                placed.insert(b.key)
            } else {
                result += b.text
            }
            last = b.range.upperBound
        }
        result += existing[last...]
        for key in order where !placed.contains(key) {
            result = result.trimmingTrailingWhitespace() + "\n\n" + fresh[key]!
        }
        return result
    }
}

extension String {
    func trimmingTrailingWhitespace() -> String {
        var s = self
        while let c = s.last, c.isWhitespace { s.removeLast() }
        return s
    }
}

// MARK: - Models

struct HclTag: Hashable, Sendable {
    let key: String
    let value: String
}

struct Ec2InstanceHcl: Sendable {
    var resourceName = "main"
    var amiId = ""
    var instanceType = "t3.micro"
    var subnetId: String?
    var associatePublicIp = false
    var securityGroupIds: [String] = []
    var keyName: String?
    var iamInstanceProfile: String?
    var monitoring = false
    var disableApiTermination = false
    var userData: String?
    var rootVolumeGb = 20
    var rootVolumeType = "gp3"
    var deleteOnTermination = true
    var tags: [HclTag] = []
}

struct S3BucketHcl: Sendable {
    var resourceName = "main"
    var bucketName = ""
    var forceDestroy = false
    var blockPublicAcls = true
    var blockPublicPolicy = true
    var ignorePublicAcls = true
    var restrictPublicBuckets = true
    var versioning = false
    var serverSideEncryption = true
    var loggingTargetBucket: String?
    var loggingTargetPrefix: String?
    var tags: [HclTag] = []
}

struct SecurityGroupHcl: Sendable {
    struct Rule: Sendable {
        var description = ""
        var fromPort = 0
        var toPort = 0
        var proto = "tcp"
        var cidrBlocks = ["0.0.0.0/0"]
    }

    var resourceName = "main"
    var name = ""
    var description = "Managed by Atlas"
    var vpcId: String?
    var ingress: [Rule] = []
    var egress: [Rule] = [Rule(description: "Allow all outbound", fromPort: 0, toPort: 0, proto: "-1")]
    var tags: [HclTag] = []

    static func webServer(_ name: String, vpcId: String? = nil) -> Self {
        SecurityGroupHcl(resourceName: name, name: name, description: "Web server security group", vpcId: vpcId,
                         ingress: [Rule(description: "HTTPS", fromPort: 443, toPort: 443),
                                   Rule(description: "HTTP", fromPort: 80, toPort: 80)])
    }
}

struct IamRoleHcl: Sendable {
    struct InlinePolicy: Sendable {
        var name: String
        var document: String
    }

    var resourceName = "main"
    var roleName = ""
    var description = "Managed by Atlas"
    var principalService = "ec2.amazonaws.com"
    var maxSessionDuration = 3600
    var permissionsBoundary: String?
    var managedPolicyArns: [String] = []
    var inlinePolicies: [InlinePolicy] = []
    var tags: [HclTag] = []

    static func lambdaExecution(_ name: String) -> Self {
        IamRoleHcl(resourceName: name, roleName: name, description: "Lambda execution role",
                   principalService: "lambda.amazonaws.com",
                   managedPolicyArns: ["arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"])
    }

    static func ec2InstanceProfile(_ name: String) -> Self {
        IamRoleHcl(resourceName: name, roleName: name, description: "EC2 instance profile role",
                   managedPolicyArns: ["arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"])
    }
}

// MARK: - Generator

/// Renders the HCL of Atlas 1.0.1's Scriban templates (ec2_instance, s3_bucket, security_group, iam_role,
/// modules/ec2 and modules/s3) and writes it into a project, merging with what is already there.
enum HclGenerator {
    /// A valid Terraform identifier from any name: lowercase, `[a-z0-9_]`, not starting with a digit.
    static func identifier(_ raw: String, fallback: String = "resource") -> String {
        let lowered = raw.lowercased().map { c -> Character in c == " " || c == "-" || c == "." ? "_" : c }
        var s = String(lowered.filter { ("a"..."z").contains($0) || ("0"..."9").contains($0) || $0 == "_" })
        while let f = s.first, f.isNumber { s.removeFirst() }
        return s.isEmpty ? fallback : s
    }

    /// A double-quoted HCL string; `${` and `%{` are escaped so values never become interpolations.
    static func quote(_ s: String) -> String {
        let escaped = s.replacingOccurrences(of: "\\", with: "\\\\").replacingOccurrences(of: "\"", with: "\\\"")
            .replacingOccurrences(of: "\n", with: "\\n").replacingOccurrences(of: "${", with: "$${")
            .replacingOccurrences(of: "%{", with: "%%{")
        return "\"\(escaped)\""
    }

    private static func header(_ template: String, ownership: Bool = false) -> String {
        var h = """
        # ─────────────────────────────────────────────────────────────────────────────
        # Generated by Atlas IaC Generator  •  \(template)

        """
        if ownership {
            h += """
            # Content inside ATLAS-MANAGED markers is regenerated on each run.
            # Content OUTSIDE those markers is yours — Atlas will never overwrite it.

            """
        }
        return h + "# ─────────────────────────────────────────────────────────────────────────────\n"
    }

    private static func managed(_ key: String, _ body: String) -> String {
        "\(HclMerge.markerStart) \(key)\n\(body)\n\(HclMerge.markerEnd) \(key)"
    }

    private static func tagLines(_ tags: [HclTag], indent: String = "    ") -> String {
        tags.map { "\n\(indent)\(quote($0.key)) = \(quote($0.value))" }.joined()
    }

    static func ec2Instance(_ m: Ec2InstanceHcl) -> String {
        let r = m.resourceName
        var b = "resource \"aws_instance\" \"\(r)\" {\n  ami           = \(quote(m.amiId))\n  instance_type = \(quote(m.instanceType))"
        if let s = m.subnetId, !s.isEmpty { b += "\n  subnet_id = \(quote(s))" }
        if m.associatePublicIp { b += "\n  associate_public_ip_address = true" }
        if !m.securityGroupIds.isEmpty {
            b += "\n  vpc_security_group_ids = [" + m.securityGroupIds.map { "\n    \(quote($0))," }.joined() + "\n  ]"
        }
        if let k = m.keyName, !k.isEmpty { b += "\n  key_name = \(quote(k))" }
        if let p = m.iamInstanceProfile, !p.isEmpty { b += "\n  iam_instance_profile = \(quote(p))" }
        if m.disableApiTermination { b += "\n  disable_api_termination = true" }
        if m.monitoring { b += "\n  monitoring = true" }
        if let u = m.userData, !u.isEmpty {
            let body = u.split(separator: "\n", omittingEmptySubsequences: false).map { "    \($0)" }.joined(separator: "\n")
            b += "\n  user_data = base64encode(<<-EOF\n\(body)\n  EOF\n  )"
        }
        b += """


          root_block_device {
            volume_type           = \(quote(m.rootVolumeType))
            volume_size           = \(m.rootVolumeGb)
            delete_on_termination = \(m.deleteOnTermination)
            encrypted             = true
          }

          tags = {
            Name      = \(quote(r))
            ManagedBy = "Atlas"\(tagLines(m.tags))
          }

          lifecycle {
            # root_block_device is ignored because AWS forbids shrinking an EBS volume:
            # if the generated size is ever smaller than the live volume, apply fails
            # with "New size cannot be smaller than existing size". Ignoring the block
            # also avoids accidental, destructive volume changes on imported instances.
            ignore_changes = [ami, user_data, root_block_device]
          }
        }
        """
        return header("template: ec2_instance", ownership: true) + "\n"
            + managed("resource \"aws_instance\" \"\(r)\"", b) + "\n"
    }

    static func s3Bucket(_ m: S3BucketHcl) -> String {
        let r = m.resourceName
        var b = "resource \"aws_s3_bucket\" \"\(r)\" {\n  bucket        = \(quote(m.bucketName))"
        if m.forceDestroy { b += "\n  force_destroy = true" }
        if !m.tags.isEmpty { b += "\n\n  tags = {\(tagLines(m.tags))\n  }" }
        b += "\n}"
        var out = header("template: s3_bucket") + "\n" + managed("resource \"aws_s3_bucket\" \"\(r)\"", b)

        if m.blockPublicAcls || m.blockPublicPolicy || m.ignorePublicAcls || m.restrictPublicBuckets {
            out += "\n\n" + managed("resource \"aws_s3_bucket_public_access_block\" \"\(r)\"", """
            resource "aws_s3_bucket_public_access_block" "\(r)" {
              bucket = aws_s3_bucket.\(r).id

              block_public_acls       = \(m.blockPublicAcls)
              block_public_policy     = \(m.blockPublicPolicy)
              ignore_public_acls      = \(m.ignorePublicAcls)
              restrict_public_buckets = \(m.restrictPublicBuckets)
            }
            """)
        }
        if m.versioning {
            out += "\n\n" + managed("resource \"aws_s3_bucket_versioning\" \"\(r)\"", """
            resource "aws_s3_bucket_versioning" "\(r)" {
              bucket = aws_s3_bucket.\(r).id

              versioning_configuration {
                status = "Enabled"
              }
            }
            """)
        }
        if m.serverSideEncryption {
            out += "\n\n" + managed("resource \"aws_s3_bucket_server_side_encryption_configuration\" \"\(r)\"", """
            resource "aws_s3_bucket_server_side_encryption_configuration" "\(r)" {
              bucket = aws_s3_bucket.\(r).id

              rule {
                apply_server_side_encryption_by_default {
                  sse_algorithm = "AES256"
                }
                bucket_key_enabled = true
              }
            }
            """)
        }
        if let target = m.loggingTargetBucket, !target.isEmpty {
            out += "\n\n" + managed("resource \"aws_s3_bucket_logging\" \"\(r)\"", """
            resource "aws_s3_bucket_logging" "\(r)" {
              bucket        = aws_s3_bucket.\(r).id
              target_bucket = \(quote(target))
              target_prefix = \(quote(m.loggingTargetPrefix ?? ""))
            }
            """)
        }
        return out + "\n"
    }

    static func securityGroup(_ m: SecurityGroupHcl) -> String {
        let r = m.resourceName
        func rule(_ kind: String, _ x: SecurityGroupHcl.Rule) -> String {
            """


              \(kind) {
                description = \(quote(x.description))
                from_port   = \(x.fromPort)
                to_port     = \(x.toPort)
                protocol    = \(quote(x.proto))
                cidr_blocks = [\(x.cidrBlocks.map { "\n      \(quote($0))," }.joined())
                ]
              }
            """
        }
        var b = "resource \"aws_security_group\" \"\(r)\" {\n  name        = \(quote(m.name))\n  description = \(quote(m.description))"
        if let v = m.vpcId, !v.isEmpty { b += "\n  vpc_id      = \(quote(v))" }
        b += m.ingress.map { rule("ingress", $0) }.joined() + m.egress.map { rule("egress", $0) }.joined()
        b += """


          tags = {
            Name      = \(quote(m.name))
            ManagedBy = "Atlas"\(tagLines(m.tags))
          }

          lifecycle {
            create_before_destroy = true
          }
        }
        """
        return header("template: security_group") + "\n" + managed("resource \"aws_security_group\" \"\(r)\"", b) + "\n"
    }

    static func iamRole(_ m: IamRoleHcl) -> String {
        let r = m.resourceName
        var b = """
        resource "aws_iam_role" "\(r)" {
          name                = \(quote(m.roleName))
          description         = \(quote(m.description))
          max_session_duration = \(m.maxSessionDuration)

          assume_role_policy = jsonencode({
            Version = "2012-10-17"
            Statement = [
              {
                Effect    = "Allow"
                Principal = { Service = \(quote(m.principalService)) }
                Action    = "sts:AssumeRole"
              }
            ]
          })
        """
        if let pb = m.permissionsBoundary, !pb.isEmpty { b += "\n  permissions_boundary = \(quote(pb))" }
        b += "\n\n  tags = {\n    Name      = \(quote(m.roleName))\n    ManagedBy = \"Atlas\"\(tagLines(m.tags))\n  }\n}"
        var out = header("template: iam_role") + "\n" + managed("resource \"aws_iam_role\" \"\(r)\"", b)
        for p in m.inlinePolicies {
            let name = "\(r)_\(identifier(p.name, fallback: "policy"))"
            out += "\n\n" + managed("resource \"aws_iam_role_policy\" \"\(name)\"", """
            resource "aws_iam_role_policy" "\(name)" {
              name   = \(quote(p.name))
              role   = aws_iam_role.\(r).id
              policy = jsonencode(\(p.document))
            }
            """)
        }
        for arn in m.managedPolicyArns {
            let name = "\(r)_\(arn.replacingOccurrences(of: ":", with: "_").replacingOccurrences(of: "/", with: "_"))"
            out += "\n\n" + managed("resource \"aws_iam_role_policy_attachment\" \"\(name)\"", """
            resource "aws_iam_role_policy_attachment" "\(name)" {
              role       = aws_iam_role.\(r).name
              policy_arn = \(quote(arn))
            }
            """)
        }
        return out + "\n"
    }

    // MARK: Modules

    private static func variable(_ name: String, _ description: String, _ type: String, _ defaultValue: String?) -> String {
        managed("variable \"\(name)\"", """
        variable "\(name)" {
          description = \(quote(description))
          type        = \(type)\(defaultValue.map { "\n  default     = \($0)" } ?? "")
        }
        """)
    }

    private static func output(_ name: String, _ description: String, _ value: String) -> String {
        managed("output \"\(name)\"", """
        output "\(name)" {
          description = \(quote(description))
          value       = \(value)
        }
        """)
    }

    /// main.tf, variables.tf and outputs.tf of the reusable EC2 module.
    static func ec2Module(_ m: Ec2InstanceHcl) -> [String: String] {
        var main = "resource \"aws_instance\" \"this\" {\n  ami           = var.ami_id\n  instance_type = var.instance_type\n"
        if m.subnetId?.isEmpty == false { main += "\n  subnet_id = var.subnet_id" }
        if !m.securityGroupIds.isEmpty { main += "\n  vpc_security_group_ids = var.security_group_ids" }
        if m.keyName?.isEmpty == false { main += "\n  key_name = var.key_name" }
        if m.iamInstanceProfile?.isEmpty == false { main += "\n  iam_instance_profile = var.iam_instance_profile" }
        main += """


          monitoring                  = var.monitoring
          associate_public_ip_address = var.associate_public_ip_address
          disable_api_termination     = var.disable_api_termination

          root_block_device {
            volume_type           = var.root_volume_type
            volume_size           = var.root_volume_size_gb
            delete_on_termination = var.delete_on_termination
            encrypted             = true
          }

          tags = merge(var.tags, {
            Name      = var.name
            ManagedBy = "Atlas"
          })

          lifecycle {
            ignore_changes = [ami]
          }
        }
        """
        let variables = [
            variable("ami_id", "AMI ID for the EC2 instance", "string", nil),
            variable("instance_type", "EC2 instance type", "string", quote(m.instanceType)),
            variable("name", "Name tag for the instance", "string", nil),
            variable("subnet_id", "Subnet ID to launch the instance in", "string", "null"),
            variable("security_group_ids", "List of security group IDs", "list(string)", "[]"),
            variable("key_name", "Key pair name for SSH access", "string", "null"),
            variable("iam_instance_profile", "IAM instance profile name", "string", "null"),
            variable("root_volume_size_gb", "Root EBS volume size in GiB", "number", "\(m.rootVolumeGb)"),
            variable("root_volume_type", "Root EBS volume type", "string", quote(m.rootVolumeType)),
            variable("monitoring", "Enable detailed monitoring", "bool", "false"),
            variable("associate_public_ip_address", "Whether to associate a public IP address", "bool", "false"),
            variable("disable_api_termination", "Protect instance from accidental termination", "bool", "false"),
            variable("delete_on_termination", "Delete root volume on instance termination", "bool", "true"),
            variable("tags", "Additional resource tags", "map(string)", "{}"),
        ]
        let outputs = [
            output("instance_id", "EC2 instance ID", "aws_instance.this.id"),
            output("instance_arn", "EC2 instance ARN", "aws_instance.this.arn"),
            output("private_ip", "Private IP address", "aws_instance.this.private_ip"),
            output("public_ip", "Public IP address (null if not associated)", "aws_instance.this.public_ip"),
        ]
        return [
            "main.tf": header("module: ec2") + "\n" + managed("resource \"aws_instance\" \"this\"", main) + "\n",
            "variables.tf": header("module: ec2/variables") + "\n" + variables.joined(separator: "\n\n") + "\n",
            "outputs.tf": header("module: ec2/outputs") + "\n" + outputs.joined(separator: "\n\n") + "\n",
        ]
    }

    /// main.tf, variables.tf and outputs.tf of the reusable S3 module.
    static func s3Module(_ m: S3BucketHcl) -> [String: String] {
        let main = [
            managed("resource \"aws_s3_bucket\" \"this\"", """
            resource "aws_s3_bucket" "this" {
              bucket        = var.bucket_name
              force_destroy = var.force_destroy

              tags = merge(var.tags, {
                Name      = var.bucket_name
                ManagedBy = "Atlas"
              })
            }
            """),
            managed("resource \"aws_s3_bucket_public_access_block\" \"this\"", """
            resource "aws_s3_bucket_public_access_block" "this" {
              bucket                  = aws_s3_bucket.this.id
              block_public_acls       = var.block_public_acls
              block_public_policy     = var.block_public_policy
              ignore_public_acls      = var.ignore_public_acls
              restrict_public_buckets = var.restrict_public_buckets
            }
            """),
            managed("resource \"aws_s3_bucket_versioning\" \"this\"", """
            resource "aws_s3_bucket_versioning" "this" {
              bucket = aws_s3_bucket.this.id

              versioning_configuration {
                status = var.versioning_enabled ? "Enabled" : "Suspended"
              }
            }
            """),
            managed("resource \"aws_s3_bucket_server_side_encryption_configuration\" \"this\"", """
            resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
              bucket = aws_s3_bucket.this.id

              rule {
                apply_server_side_encryption_by_default {
                  sse_algorithm = "AES256"
                }
                bucket_key_enabled = true
              }
            }
            """),
        ]
        let variables = [
            variable("bucket_name", "S3 bucket name (globally unique)", "string", nil),
            variable("force_destroy", "Delete all objects when destroying the bucket", "bool", "false"),
            variable("versioning_enabled", "Enable S3 versioning", "bool", "\(m.versioning)"),
            variable("block_public_acls", "Block public ACLs", "bool", "true"),
            variable("block_public_policy", "Block public bucket policies", "bool", "true"),
            variable("ignore_public_acls", "Ignore public ACLs", "bool", "true"),
            variable("restrict_public_buckets", "Restrict public bucket policies", "bool", "true"),
            variable("tags", "Additional resource tags", "map(string)", "{}"),
        ]
        let outputs = [
            output("bucket_id", "S3 bucket name (same as ID)", "aws_s3_bucket.this.id"),
            output("bucket_arn", "S3 bucket ARN", "aws_s3_bucket.this.arn"),
            output("bucket_domain_name", "S3 bucket domain name", "aws_s3_bucket.this.bucket_domain_name"),
            output("bucket_regional_domain_name", "S3 bucket regional domain name",
                   "aws_s3_bucket.this.bucket_regional_domain_name"),
        ]
        return [
            "main.tf": header("module: s3") + "\n" + main.joined(separator: "\n\n") + "\n",
            "variables.tf": header("module: s3/variables") + "\n" + variables.joined(separator: "\n\n") + "\n",
            "outputs.tf": header("module: s3/outputs") + "\n" + outputs.joined(separator: "\n\n") + "\n",
        ]
    }

    // MARK: Writing

    struct WriteResult {
        let path: URL
        let wasWritten: Bool
        let keys: [String]
    }

    /// Merges `content` into `file` (creating it if needed) and writes atomically.
    /// With `overwriteManaged == false`, a file that already has every block is left untouched.
    @discardableResult
    static func write(_ content: String, to file: URL, overwriteManaged: Bool = true) throws -> WriteResult {
        let rendered = content.trimmingTrailingWhitespace() + "\n"
        let keys = HclMerge.keys(rendered)
        let final: String
        if let existing = try? String(contentsOf: file, encoding: .utf8) {
            if !overwriteManaged, Set(keys).isSubset(of: HclMerge.keys(existing)) {
                return WriteResult(path: file, wasWritten: false, keys: keys)
            }
            final = HclMerge.merge(existing: existing, new: rendered)
        } else {
            try FileManager.default.createDirectory(at: file.deletingLastPathComponent(), withIntermediateDirectories: true)
            final = rendered
        }
        try Data(final.utf8).write(to: file, options: .atomic)
        return WriteResult(path: file, wasWritten: true, keys: keys)
    }

    /// Writes a module's files into `directory`.
    static func writeModule(_ files: [String: String], to directory: URL) throws -> [WriteResult] {
        try files.keys.sorted().map { try write(files[$0]!, to: directory.appendingPathComponent($0)) }
    }
}
